INSERT INTO reports (id, created_at, updated_at, title, description, image_url, image_urls, latitude, longitude, address, location_description, severity, status, user_id, assigned_staff_id, category_id, is_anonymous, assigned_at, resolved_at, resolved_note, resolved_image_urls, is_review_resolved, rating, review_note, review_image_urls, reviewed_at, deadline, rejected_reason, rejected_at) VALUES
('r01', DATE_SUB(NOW(), INTERVAL 2517600 SECOND), DATE_SUB(NOW(), INTERVAL 2473200 SECOND), 'Mất nắp hố ga trên đường Nguyễn Thị Minh Khai', 'Nắp hố ga trước số 112 Nguyễn Thị Minh Khai bị mất từ tối qua, người dân chỉ cắm tạm vài cành cây để cảnh báo. Đoạn này xe máy rất đông, buổi tối rất dễ sa bánh xuống hố.', 'https://picsum.photos/seed/r01-1/800/600', 'https://picsum.photos/seed/r01-1/800/600,https://picsum.photos/seed/r01-2/800/600', 10.779812, 106.693045, '112 Nguyễn Thị Minh Khai, Phường Xuân Hòa, TP. Hồ Chí Minh', 'Sát lề phải, trước cửa hàng tiện lợi', 'high', 'processed', 'u11', 'u5', 'cat_infra', FALSE, DATE_SUB(NOW(), INTERVAL 2514900 SECOND), DATE_SUB(NOW(), INTERVAL 2498400 SECOND), 'Đã lắp nắp gang mới loại chịu tải 25 tấn, trám vữa cố định và dọn biển cảnh báo tạm.', 'https://picsum.photos/seed/r01-done-1/800/600,https://picsum.photos/seed/r01-done-2/800/600', TRUE, 5, 'Xử lý rất nhanh, buổi chiều đã có nắp mới. Cảm ơn anh em kỹ thuật!', NULL, DATE_SUB(NOW(), INTERVAL 2473200 SECOND), DATE_ADD(DATE_SUB(NOW(), INTERVAL 2514900 SECOND), INTERVAL 7 DAY), NULL, NULL),
('r02', DATE_SUB(NOW(), INTERVAL 2449200 SECOND), DATE_SUB(NOW(), INTERVAL 2264400 SECOND), 'Cả dãy đèn đường không sáng', 'Khoảng 6 cột đèn trên đường Sư Vạn Hạnh, đoạn từ Ngô Gia Tự tới đường 3 Tháng 2, tắt hết 3 đêm nay. Đường tối om, tuần rồi trong hẻm có người bị giật điện thoại.', 'https://picsum.photos/seed/r02-1/800/600', 'https://picsum.photos/seed/r02-1/800/600', 10.773512, 106.668803, 'Đường Sư Vạn Hạnh, Phường Diên Hồng, TP. Hồ Chí Minh', 'Đoạn giữa Ngô Gia Tự và 3 Tháng 2', 'medium', 'processed', 'u3', 'u8', 'cat_elec', FALSE, DATE_SUB(NOW(), INTERVAL 2438400 SECOND), DATE_SUB(NOW(), INTERVAL 2308800 SECOND), 'Thay CB tổng tủ điều khiển chiếu sáng bị cháy, kiểm tra lại 6 bộ đèn, tất cả đã sáng bình thường.', 'https://picsum.photos/seed/r02-done-1/800/600', TRUE, 4, 'Đèn sáng lại rồi nhưng gần 2 ngày mới có người xuống kiểm tra.', NULL, DATE_SUB(NOW(), INTERVAL 2264400 SECOND), DATE_ADD(DATE_SUB(NOW(), INTERVAL 2438400 SECOND), INTERVAL 5 DAY), NULL, NULL),
('r03', DATE_SUB(NOW(), INTERVAL 2350800 SECOND), DATE_SUB(NOW(), INTERVAL 2282400 SECOND), 'Rác tồn đọng ở điểm tập kết đầu hẻm', 'Điểm tập kết rác đầu hẻm 51 Cao Thắng không được thu gom 3 ngày, rác tràn ra lòng hẻm, ruồi nhặng nhiều và mùi hôi rất nặng.', 'https://picsum.photos/seed/r03-1/800/600', 'https://picsum.photos/seed/r03-1/800/600,https://picsum.photos/seed/r03-2/800/600', 10.771215, 106.681842, 'Hẻm 51 Cao Thắng, Phường Bàn Cờ, TP. Hồ Chí Minh', 'Đầu hẻm, cạnh trụ điện', 'low', 'processed', 'u12', 'u6', 'cat_env', FALSE, DATE_SUB(NOW(), INTERVAL 2343600 SECOND), DATE_SUB(NOW(), INTERVAL 2322000 SECOND), 'Đã điều xe thu gom, rửa nền và rải vôi bột khử mùi. Đã nhắc đơn vị thu gom giữ lịch cố định 19h hằng ngày.', 'https://picsum.photos/seed/r03-done-1/800/600', TRUE, 5, NULL, NULL, DATE_SUB(NOW(), INTERVAL 2282400 SECOND), DATE_ADD(DATE_SUB(NOW(), INTERVAL 2343600 SECOND), INTERVAL 3 DAY), NULL, NULL),
('r04', DATE_SUB(NOW(), INTERVAL 2251800 SECOND), DATE_SUB(NOW(), INTERVAL 2202000 SECOND), 'Vỡ ống cấp nước, nước tràn mặt đường', 'Ống cấp nước dưới vỉa hè trước số 45 Phan Đăng Lưu bị vỡ, nước phun lên mặt đường từ 5h sáng. Mấy dãy nhà xung quanh mất nước sinh hoạt.', 'https://picsum.photos/seed/r04-1/800/600', 'https://picsum.photos/seed/r04-1/800/600,https://picsum.photos/seed/r04-2/800/600,https://picsum.photos/seed/r04-3/800/600', 10.803021, 106.695514, '45 Phan Đăng Lưu, Phường Gia Định, TP. Hồ Chí Minh', 'Vỉa hè trước nhà số 45', 'high', 'processed', 'u15', 'u5', 'cat_water', FALSE, DATE_SUB(NOW(), INTERVAL 2250000 SECOND), DATE_SUB(NOW(), INTERVAL 2235600 SECOND), 'Phối hợp đơn vị cấp nước khoá van tổng, thay đoạn ống HDPE D110 dài 2m, nước đã có lại lúc 10h30.', 'https://picsum.photos/seed/r04-done-1/800/600,https://picsum.photos/seed/r04-done-2/800/600', TRUE, 5, 'Rất chuyên nghiệp, có thông báo trước giờ cúp nước.', NULL, DATE_SUB(NOW(), INTERVAL 2202000 SECOND), DATE_ADD(DATE_SUB(NOW(), INTERVAL 2250000 SECOND), INTERVAL 7 DAY), NULL, NULL),
