('r21', DATE_SUB(NOW(), INTERVAL 345600 SECOND), DATE_SUB(NOW(), INTERVAL 120000 SECOND), 'Cống thoát nước bị tắc trước trường tiểu học', 'Cống thoát nước trên đường Lý Thường Kiệt trước cổng trường tiểu học bị rác và bùn lấp kín, mưa 30 phút là nước ngập tới mắt cá, học sinh phải lội nước vào trường.', 'https://picsum.photos/seed/r21-1/800/600', 'https://picsum.photos/seed/r21-1/800/600,https://picsum.photos/seed/r21-2/800/600,https://picsum.photos/seed/r21-3/800/600', 10.769034, 106.662015, 'Đường Lý Thường Kiệt, Phường Diên Hồng, TP. Hồ Chí Minh', 'Trước cổng trường tiểu học', 'critical', 'processed', 'u3', 'u5', 'cat_water', FALSE, DATE_SUB(NOW(), INTERVAL 252000 SECOND), DATE_SUB(NOW(), INTERVAL 172800 SECOND), 'Đã nạo vét toàn bộ tuyến cống dài 40m, thay 2 song chắn rác bị gãy.', 'https://picsum.photos/seed/r21-done-1/800/600,https://picsum.photos/seed/r21-done-2/800/600', TRUE, 5, 'Mưa chiều qua không còn ngập nữa, cảm ơn!', NULL, DATE_SUB(NOW(), INTERVAL 120000 SECOND), DATE_ADD(DATE_SUB(NOW(), INTERVAL 252000 SECOND), INTERVAL 10 DAY), NULL, NULL),
