('r32', DATE_SUB(NOW(), INTERVAL 28800 SECOND), DATE_SUB(NOW(), INTERVAL 14400 SECOND), 'Cành cây lớn gãy treo lơ lửng trên đường', 'Cành cây dầu lớn trong công viên Lê Văn Tám gãy, treo lơ lửng ngay phía trên làn xe máy đường Hai Bà Trưng, gió thổi là đung đưa.', 'https://picsum.photos/seed/r32-1/800/600', 'https://picsum.photos/seed/r32-1/800/600,https://picsum.photos/seed/r32-2/800/600', 10.788012, 106.696015, 'Đường Hai Bà Trưng (công viên Lê Văn Tám), Phường Tân Định, TP. Hồ Chí Minh', 'Phía trên làn xe máy', 'high', 'processing', 'u12', 'u6', 'cat_env', FALSE, DATE_SUB(NOW(), INTERVAL 14400 SECOND), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, DATE_ADD(DATE_SUB(NOW(), INTERVAL 14400 SECOND), INTERVAL 7 DAY), NULL, NULL),
('r43', DATE_SUB(NOW(), INTERVAL 22800 SECOND), DATE_SUB(NOW(), INTERVAL 22800 SECOND), 'Xe tải làm rơi vãi đất cát ra đường', 'Xe ben chở đất không phủ bạt làm rơi vãi đất cát dài cả trăm mét trên đường Kinh Dương Vương, xe máy trượt bánh rất nhiều.', 'https://picsum.photos/seed/r43-1/800/600', 'https://picsum.photos/seed/r43-1/800/600,https://picsum.photos/seed/r43-2/800/600', 10.733012, 106.621015, 'Đường Kinh Dương Vương, Phường An Lạc, TP. Hồ Chí Minh', 'Gần vòng xoay', 'medium', 'pending', 'u21', NULL, 'cat_infra', FALSE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('r33', DATE_SUB(NOW(), INTERVAL 18000 SECOND), DATE_SUB(NOW(), INTERVAL 14400 SECOND), 'Đồng hồ nước tổng của hẻm bị rò rỉ', 'Đồng hồ nước tổng đầu hẻm 230 Lý Thường Kiệt bị rò ở khớp nối, nước chảy liên tục cả ngày đêm, áp lực nước trong hẻm yếu hẳn.', 'https://picsum.photos/seed/r33-1/800/600', 'https://picsum.photos/seed/r33-1/800/600,https://picsum.photos/seed/r33-2/800/600', 10.766012, 106.660015, 'Hẻm 230 Lý Thường Kiệt, Phường Diên Hồng, TP. Hồ Chí Minh', 'Đầu hẻm', 'medium', 'processing', 'u15', 'u5', 'cat_water', FALSE, DATE_SUB(NOW(), INTERVAL 14400 SECOND), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, DATE_ADD(DATE_SUB(NOW(), INTERVAL 14400 SECOND), INTERVAL 5 DAY), NULL, NULL),
('r34', DATE_SUB(NOW(), INTERVAL 12000 SECOND), DATE_SUB(NOW(), INTERVAL 10200 SECOND), 'Ống nước chính bị vỡ, cả khu mất nước', 'Đơn vị thi công đào trúng ống nước chính trên đường Nguyễn Văn Đậu, nước phun cao hơn 1m, cả khu dân cư mất nước từ trưa.', 'https://picsum.photos/seed/r34-1/800/600', 'https://picsum.photos/seed/r34-1/800/600,https://picsum.photos/seed/r34-2/800/600,https://picsum.photos/seed/r34-3/800/600', 10.810512, 106.692015, 'Đường Nguyễn Văn Đậu, TP. Hồ Chí Minh', 'Công trường đào đường', 'critical', 'processing', 'u21', 'u5', 'cat_water', FALSE, DATE_SUB(NOW(), INTERVAL 10200 SECOND), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, DATE_ADD(DATE_SUB(NOW(), INTERVAL 10200 SECOND), INTERVAL 10 DAY), NULL, NULL),
('r42', DATE_SUB(NOW(), INTERVAL 11400 SECOND), DATE_SUB(NOW(), INTERVAL 11400 SECOND), 'Ổ gà lớn trên đường Cộng Hòa', 'Ổ gà đường kính gần 1m ngay làn xe máy đường Cộng Hòa hướng ra sân bay, trời mưa đọng nước không thấy, đã có người té xe.', 'https://picsum.photos/seed/r42-1/800/600', 'https://picsum.photos/seed/r42-1/800/600,https://picsum.photos/seed/r42-2/800/600', 10.802012, 106.650015, 'Đường Cộng Hòa, Phường Tân Bình, TP. Hồ Chí Minh', 'Làn xe máy hướng ra sân bay', 'medium', 'pending', 'u16', NULL, 'cat_infra', FALSE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('r35', DATE_SUB(NOW(), INTERVAL 7800 SECOND), DATE_SUB(NOW(), INTERVAL 6900 SECOND), 'Dây điện chạm chập tóe lửa trên cột', 'Dây điện trên cột trước số 88 Quang Trung chạm chập, tóe lửa liên tục và có mùi khét, người dân không dám đi qua.', 'https://picsum.photos/seed/r35-1/800/600', 'https://picsum.photos/seed/r35-1/800/600', 10.835012, 106.664015, '88 Quang Trung, Phường Gò Vấp, TP. Hồ Chí Minh', 'Cột điện trước nhà số 88', 'critical', 'processing', 'u7', 'u8', 'cat_elec', FALSE, DATE_SUB(NOW(), INTERVAL 6900 SECOND), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, DATE_ADD(DATE_SUB(NOW(), INTERVAL 6900 SECOND), INTERVAL 10 DAY), NULL, NULL),
('r41', DATE_SUB(NOW(), INTERVAL 6000 SECOND), DATE_SUB(NOW(), INTERVAL 6000 SECOND), 'Street flooded after heavy rain, not draining', 'Nguyen Van Huong street has been flooded for over an hour after the rain stopped. Water is about 30 cm deep and is not draining at all.', 'https://picsum.photos/seed/r41-1/800/600', 'https://picsum.photos/seed/r41-1/800/600,https://picsum.photos/seed/r41-2/800/600', 10.808012, 106.733015, 'Đường Nguyễn Văn Hưởng, Phường An Khánh, TP. Hồ Chí Minh', 'In front of the international school', 'medium', 'pending', 'u20', NULL, 'cat_water', FALSE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('r40', DATE_SUB(NOW(), INTERVAL 3000 SECOND), DATE_SUB(NOW(), INTERVAL 3000 SECOND), 'Cây đổ chắn ngang đường sau cơn mưa', 'Cây xà cừ lớn bật gốc sau cơn mưa, đổ chắn ngang đường Phạm Ngọc Thạch, xe phải quay đầu đi đường khác.', 'https://picsum.photos/seed/r40-1/800/600', 'https://picsum.photos/seed/r40-1/800/600,https://picsum.photos/seed/r40-2/800/600,https://picsum.photos/seed/r40-3/800/600', 10.786012, 106.695015, 'Đường Phạm Ngọc Thạch, Phường Xuân Hòa, TP. Hồ Chí Minh', 'Đoạn gần hồ Con Rùa', 'high', 'pending', 'u11', NULL, 'cat_env', FALSE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('r39', DATE_SUB(NOW(), INTERVAL 1500 SECOND), DATE_SUB(NOW(), INTERVAL 1500 SECOND), 'Ngửi thấy mùi gas nồng nặc ở sảnh chung cư', 'Sảnh tầng trệt block B có mùi gas rất nồng từ 15 phút trước, bảo vệ chưa tìm được chỗ rò. Mọi người đang tự sơ tán ra ngoài.', 'https://picsum.photos/seed/r39-1/800/600', 'https://picsum.photos/seed/r39-1/800/600', 10.842012, 106.638015, 'Đường Phan Huy Ích, TP. Hồ Chí Minh', 'Sảnh tầng trệt block B', 'critical', 'pending', 'u14', NULL, 'cat_order', TRUE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
