INSERT INTO chat_messages (id, conversation_id, sender_id, content, message_type, sent_at) VALUES
('m001', 'c1', 'u2', 'Anh ơi, đường 3 Tháng 2 trước nhà anh có còn ngập không? Chiều nay em định chạy qua.', 'text', DATE_SUB(NOW(), INTERVAL 180000 SECOND)),
('m002', 'c1', 'u3', 'Hôm qua ngập tới mắt cá, cống trước trường bị nghẹt. Anh gửi phản ánh rồi, sáng nay có đội xuống nạo vét.', 'text', DATE_SUB(NOW(), INTERVAL 178500 SECOND)),
('m003', 'c1', 'u2', 'Vậy tốt quá, để em theo dõi trên app.', 'text', DATE_SUB(NOW(), INTERVAL 178200 SECOND)),
('m004', 'c1', 'u3', 'Ừ, cái nắp hố ga trước số 520 vẫn lún nha, em chạy xe cẩn thận.', 'text', DATE_SUB(NOW(), INTERVAL 18000 SECOND)),
('m005', 'c2', 'u3', 'Chào anh, nắp hố ga anh thay hôm trước giờ lún xuống khoảng 5cm rồi, xe chạy qua bị dằn mạnh lắm.', 'text', DATE_SUB(NOW(), INTERVAL 357600 SECOND)),
('m006', 'c2', 'u5', 'Dạ em chào anh, em nhận được yêu cầu xử lý lại rồi. Tấm thép tạm không chịu được tải xe tải ban đêm.', 'text', DATE_SUB(NOW(), INTERVAL 343800 SECOND)),
('m007', 'c2', 'u5', 'Em đã đặt nắp gang loại chịu tải 25 tấn, dự kiến 2 ngày nữa có hàng, em sẽ thay luôn.', 'text', DATE_SUB(NOW(), INTERVAL 343680 SECOND)),
('m008', 'c2', 'u3', 'Ok anh, cảm ơn anh nhé.', 'text', DATE_SUB(NOW(), INTERVAL 342000 SECOND)),
('m009', 'c2', 'u5', 'Nắp mới về rồi anh, chiều mai 15h em qua lắp, khu vực sẽ rào chắn khoảng 2 tiếng.', 'text', DATE_SUB(NOW(), INTERVAL 14400 SECOND)),
('m010', 'c3', 'u11', 'Anh Đức ơi, cái lô cốt bên Nguyễn Hữu Cảnh dọn chưa anh?', 'text', DATE_SUB(NOW(), INTERVAL 968400 SECOND)),
('m011', 'c3', 'u15', 'Thu hẹp lại rồi em, đi đỡ kẹt hơn nhiều. Phản ánh trên app được xử lý nhanh phết.', 'text', DATE_SUB(NOW(), INTERVAL 962400 SECOND)),
('m012', 'c3', 'u11', 'Tối nay mưa to, đoạn gần chung cư lại ngập rồi anh, em vừa gửi phản ánh.', 'text', DATE_SUB(NOW(), INTERVAL 35400 SECOND)),
('m013', 'c3', 'u15', 'Có nhân viên nhận rồi đó, anh thấy trạng thái chuyển sang đang xử lý.', 'text', DATE_SUB(NOW(), INTERVAL 31200 SECOND)),
('m014', 'c4', 'u1', 'Chào cả tổ, nhóm này dùng để điều phối nhanh các sự cố khẩn cấp ngoài giờ hành chính.', 'text', DATE_SUB(NOW(), INTERVAL 2332800 SECOND)),
('m015', 'c4', 'u8', 'Đã rõ anh.', 'text', DATE_SUB(NOW(), INTERVAL 2332200 SECOND)),
('m016', 'c4', 'u6', 'Em nhận ạ.', 'text', DATE_SUB(NOW(), INTERVAL 2331900 SECOND)),
('m017', 'c4', 'u1', 'Tối nay có cảnh báo triều cường, tổ cấp thoát nước trực giúp anh nhé.', 'text', DATE_SUB(NOW(), INTERVAL 369600 SECOND)),
('m018', 'c4', 'u5', 'Em trực ạ. Có gì em báo trong nhóm.', 'text', DATE_SUB(NOW(), INTERVAL 368400 SECOND)),
('m019', 'c4', 'u5', 'Hiện trường ống nước vỡ Nguyễn Văn Đậu, đang chờ khoá van tổng.', 'image', DATE_SUB(NOW(), INTERVAL 9000 SECOND)),
('m020', 'c4', 'u8', 'Bên Quang Trung có dây điện chạm chập, anh đang qua xử lý.', 'text', DATE_SUB(NOW(), INTERVAL 6600 SECOND)),
('m021', 'c4', 'u1', 'Ok, ưu tiên an toàn, cần hỗ trợ gì báo anh.', 'text', DATE_SUB(NOW(), INTERVAL 6000 SECOND));
